def get_styles() -> str:
    return r'''
:root{--bg:#0d1015;--panel:#151a22;--panel2:#1c222d;--line:#2b3441;--text:#f4f5f7;--muted:#9aabc0;--accent:#d58a34;--accent2:#f2aa4c;--success:#1f9d68}
*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--text)}button,input,select{font:inherit}.app{min-height:100vh;display:flex}.sidebar{width:300px;flex:0 0 300px;border-right:1px solid var(--line);padding:18px;background:#10141a;position:sticky;top:0;height:100vh;overflow:auto}.brand{display:flex;gap:14px;align-items:center;padding-bottom:20px;border-bottom:1px solid var(--line)}.brand-mark{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,var(--accent2),#a95c16);font-size:20px}.brand h1{margin:0;font-size:19px}.brand p{margin:3px 0 0;color:var(--muted);font-size:14px}.side-title{margin:22px 4px 12px;color:var(--muted);font-size:12px;font-weight:800;letter-spacing:.12em}.step-item{width:100%;display:grid;grid-template-columns:34px 1fr;gap:11px;text-align:left;padding:12px;border-radius:12px;background:transparent;color:var(--text);border:1px solid transparent;margin-bottom:7px;cursor:pointer}.step-item:hover,.step-item.active{background:var(--panel2);border-color:#394454}.step-num{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:#252d38;color:#c7d2df;font-weight:800}.step-item.active .step-num,.step-item.completed .step-num{background:var(--accent);color:white}.step-copy strong{display:block;font-size:13px;line-height:1.35}.step-copy small{display:block;color:var(--muted);margin-top:4px;font-size:11px}.overview-btn{width:100%;margin-top:18px;padding:12px;border-radius:10px;background:transparent;border:1px solid var(--line);color:var(--text);cursor:pointer}.content{flex:1;min-width:0;padding:28px 42px 34px;max-width:1240px;margin:0 auto}.progress{height:9px;background:#1d2530;border-radius:999px;overflow:hidden;margin:2px 0 20px}.progress div{height:100%;background:linear-gradient(90deg,var(--accent),#78c8d5);transition:width .25s}.step-kicker{color:#8bbdd1;font-size:13px;letter-spacing:.08em;margin-bottom:8px}#stepOperation{font-size:clamp(28px,3.4vw,42px);line-height:1.12;margin:0 0 14px}.tool-chip{display:inline-flex;padding:8px 13px;border-radius:999px;background:#1b2330;border:1px solid #334052;color:#b9cce0;font-size:13px}.step-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr);gap:24px;margin-top:20px}.image-panel,.instructions-panel,.part-card{background:var(--panel);border:1px solid var(--line);border-radius:16px}.image-panel{padding:12px}.main-image{width:100%;height:430px;object-fit:contain;border-radius:12px;background:#e8e8e8;cursor:zoom-in}.image-placeholder{height:430px;display:grid;place-items:center;color:var(--muted)}.instructions-panel{padding:6px 22px 20px}.instructions-panel h3,.parts-section h3{font-size:20px}.instruction{display:grid;grid-template-columns:34px 1fr;gap:12px;padding:16px 0;border-bottom:1px solid var(--line);align-items:start}.instruction-num{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--accent);font-weight:800}.instruction p{margin:3px 0;line-height:1.5}.continues{margin-top:15px;padding:14px;border-radius:10px;background:#202734;color:var(--muted)}.continues strong{color:#c7d7e7}.parts-section{margin-top:25px}.parts-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}.part-card{overflow:hidden}.part-img{width:100%;height:170px;object-fit:contain;background:#ececec;display:block;cursor:zoom-in}.part-body{padding:16px}.part-body h4{font-size:17px;margin:0 0 12px}.meta{color:#a8bbd0;font-size:14px;line-height:1.7}.grade-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.field label{display:block;color:#9fb0c4;font-size:12px;margin-bottom:6px}.field select,.field input{width:100%;background:#202733;color:var(--text);border:1px solid #313b49;border-radius:9px;padding:10px;outline:none}.nav-row{display:flex;gap:14px;margin-top:28px}.nav-row .primary{margin-left:auto}.primary,.secondary{border:1px solid var(--line);border-radius:11px;padding:12px 20px;font-weight:750;cursor:pointer}.primary{background:var(--accent);color:#fff;border-color:var(--accent)}.secondary{background:#151a22;color:var(--text)}button:disabled{opacity:.35;cursor:not-allowed}.overview-panel{position:fixed;inset:6% 8%;z-index:20;background:#131922;border:1px solid var(--line);border-radius:18px;padding:28px;box-shadow:0 30px 80px #000b;overflow:auto}.hidden{display:none!important}.close-overview{position:absolute;right:18px;top:12px;background:none;color:white;border:0;font-size:32px;cursor:pointer}.overview-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.overview-card{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:16px}.overview-card span{display:block;color:var(--muted);font-size:12px;margin-bottom:7px}.image-modal{display:none;position:fixed;inset:0;z-index:30;background:#000d;align-items:center;justify-content:center;padding:30px}.image-modal.show{display:flex}.image-modal img{max-width:94%;max-height:92%;border-radius:14px}@media(max-width:900px){.app{display:block}.sidebar{position:static;width:100%;height:auto}.content{padding:22px}.step-layout{grid-template-columns:1fr}.main-image,.image-placeholder{height:330px}}@media(max-width:560px){.content{padding:16px}.parts-grid{grid-template-columns:1fr}.grade-row{grid-template-columns:1fr}.nav-row{flex-wrap:wrap}.nav-row .primary{margin-left:0}.main-image,.image-placeholder{height:260px}}

.summary-view{padding-bottom:26px}.summary-hero{display:flex;gap:18px;align-items:center;padding:24px;background:linear-gradient(135deg,#151b24,#1d2632);border:1px solid var(--line);border-radius:16px;margin-bottom:18px}.summary-hero h2{font-size:34px;margin:3px 0 6px}.summary-hero p{margin:0;color:var(--muted)}.complete-icon{width:58px;height:58px;border-radius:50%;display:grid;place-items:center;background:var(--success);font-size:31px;font-weight:900}.summary-warning,.summary-success{padding:13px 16px;border-radius:10px;margin-bottom:16px}.summary-warning{background:#3a2817;border:1px solid #7b5124;color:#ffd39a}.summary-success{background:#123326;border:1px solid #256d50;color:#9ce6c5}.summary-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.summary-stats div{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px}.summary-stats span{display:block;color:var(--muted);font-size:12px;margin-bottom:7px}.summary-stats strong{font-size:25px}.summary-table-wrap{overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:16px}.summary-table{width:100%;border-collapse:collapse;min-width:980px}.summary-table th,.summary-table td{padding:12px 13px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle}.summary-table th{color:#9fb4ca;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.summary-table tr:last-child td{border-bottom:0}.summary-thumb img{width:58px;height:44px;object-fit:contain;background:#eee;border-radius:7px;display:block}.table-no-image{display:grid;place-items:center;width:58px;height:44px;background:#202733;border-radius:7px;color:var(--muted)}.grade-badge,.destination{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:750;white-space:nowrap}.grade-excellent{background:#123b2b;color:#75e1b2}.grade-working{background:#23384a;color:#8fd2ff}.grade-damaged{background:#4a3218;color:#ffc16d}.grade-scrap{background:#3a2024;color:#ff9ca7}.grade-none{color:var(--muted);background:#202733}.dest-reuse{background:#123b2b;color:#75e1b2}.dest-repair{background:#20394a;color:#8fd2ff}.dest-damaged{background:#4a3218;color:#ffc16d}.dest-scrap{background:#3a2024;color:#ff9ca7}.summary-actions{display:flex;gap:14px;margin-top:20px}.restart-btn{margin-left:auto}
@media(max-width:900px){.summary-stats{grid-template-columns:repeat(2,1fr)}.summary-hero h2{font-size:28px}}
@media(max-width:560px){.summary-stats{grid-template-columns:1fr 1fr}.summary-actions{flex-wrap:wrap}.restart-btn{margin-left:0}.summary-hero{align-items:flex-start}.complete-icon{width:46px;height:46px;flex:0 0 46px}}

/* Compact desktop layout: keeps the complete wizard step visible on a Full HD display. */
@media (min-width:1100px) and (min-height:800px){
  .sidebar{width:280px;flex-basis:280px;padding:14px}.brand{padding-bottom:14px}.brand-mark{width:40px;height:40px}.side-title{margin:14px 4px 8px}.step-item{padding:8px 10px;margin-bottom:4px;grid-template-columns:30px 1fr}.step-num{width:27px;height:27px}.step-copy strong{font-size:12px}.step-copy small{margin-top:2px;font-size:10px}.overview-btn{margin-top:10px;padding:9px}
  .content{max-width:1500px;padding:18px 34px 20px}.progress{height:7px;margin:0 0 12px}.step-kicker{font-size:12px;margin-bottom:5px}#stepOperation{font-size:clamp(26px,2.5vw,36px);margin-bottom:9px}.tool-chip{padding:6px 11px;font-size:12px}
  .step-layout{grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);gap:18px;margin-top:12px}.image-panel{padding:9px}.main-image,.image-placeholder{height:300px}.instructions-panel{padding:4px 18px 14px}.instructions-panel h3,.parts-section h3{font-size:18px;margin:14px 0 8px}.instruction{padding:11px 0}.instruction p{line-height:1.35}.continues{margin-top:10px;padding:11px}
  .parts-section{margin-top:14px}.parts-grid{grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.part-img{height:110px}.part-body{padding:11px 13px}.part-body h4{font-size:15px;margin-bottom:7px}.meta{font-size:12px;line-height:1.45}.grade-row{gap:8px;margin-top:8px}.field label{font-size:11px;margin-bottom:4px}.field select,.field input{padding:8px}.nav-row{margin-top:14px}.primary,.secondary{padding:10px 17px}
}
@media (min-width:1500px) and (min-height:900px){.main-image,.image-placeholder{height:320px}.part-img{height:118px}}



.welcome-view{min-height:calc(100vh - 56px);display:grid;place-items:center}.welcome-card{width:min(1080px,100%);display:grid;grid-template-columns:1fr 1fr;gap:28px;align-items:center;background:linear-gradient(145deg,#151a22,#11161d);border:1px solid var(--line);border-radius:24px;padding:38px;box-shadow:0 30px 80px #0007}.welcome-copy h2{font-size:clamp(38px,5vw,66px);line-height:1.02;margin:8px 0 18px}.welcome-copy p{color:var(--muted);font-size:17px;line-height:1.65;max-width:600px}.welcome-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:24px}.welcome-stats div{background:var(--panel2);border:1px solid var(--line);border-radius:13px;padding:14px}.welcome-stats span{display:block;color:var(--muted);font-size:11px;margin-bottom:7px}.welcome-stats strong{font-size:20px}.welcome-visual{min-height:430px;display:grid;place-items:center;background:#ececec;border-radius:18px;overflow:hidden}.welcome-visual img{width:100%;height:430px;object-fit:contain;cursor:zoom-in}.welcome-placeholder{color:#667;}.welcome-start{grid-column:1/-1;justify-self:center;min-width:290px;font-size:18px;padding:15px 28px;margin-top:6px}.welcome-mode .sidebar{display:none}.welcome-mode .content{max-width:none;width:100%;padding:28px 48px}
@media(max-width:900px){.welcome-card{grid-template-columns:1fr;padding:24px}.welcome-visual,.welcome-visual img{min-height:300px;height:300px}.welcome-start{grid-column:1}.welcome-mode .content{padding:20px}.welcome-view{min-height:auto}.welcome-stats{grid-template-columns:repeat(3,1fr)}}
@media(max-width:560px){.welcome-copy h2{font-size:36px}.welcome-stats{grid-template-columns:1fr}.welcome-visual,.welcome-visual img{min-height:240px;height:240px}.welcome-start{min-width:0;width:100%}}
.welcome-view.hidden{display:none!important}

@media print{body{background:#fff;color:#111}.sidebar,#stepView,.summary-actions,.overview-panel,.image-modal{display:none!important}.content{max-width:none;padding:0}.summary-view{display:block!important}.summary-hero,.summary-stats div,.summary-table-wrap{background:#fff;color:#111;border-color:#ccc;box-shadow:none}.summary-hero p,.summary-stats span{color:#555}.summary-table th,.summary-table td{border-color:#ccc;color:#111}.summary-warning,.summary-success{color:#111;background:#fff;border-color:#aaa}.grade-badge,.destination{border:1px solid #aaa;background:#fff!important;color:#111!important}}
'''
